const uint8_t* inkMeritFrame(int idx)
{
    if (idx < 0 || idx >= INK_MERIT_FRAME_COUNT) return 0;
    return INK_MERIT_FRAME_DATA[idx];
}

const InkMeritDigitMeta* inkMeritDigitMeta(int set)
{
    if (set < 0 || set >= INK_MERIT_DIGIT_SETS) return 0;
    return INK_MERIT_DIGIT_META[set];
}

const uint8_t* inkMeritDigitData(void)
{
    return INK_MERIT_DIGIT_DATA;
}
